import type { EngineInterface, Register } from 'claude-code'

// The diagnosis guard: `/zap:zap` arms it, and while it is armed the main loop
// may write only inside the project's `.zap/` directory. A completed write of
// `.zap/diagnosis.md` disarms it, the one step from read-only to writable; a
// later `/zap:zap` in the same session arms it again.

const ARMED = { plugin: 'zap', key: 'isArmed' } as const

const ZAP_DIR = '.zap'
const DIAGNOSIS = 'diagnosis.md'
const MAX_DEPTH = 256

type Located = { zapDir: string; real: string | undefined }

const refusal = (path: string, why: string): string =>
  `zap: ${path} was not written (${why}). zap must write ${ZAP_DIR}/${DIAGNOSIS} ` +
  `before changing source: until that write succeeds, only files inside ${ZAP_DIR}/ may be written.`

const separatorOf = (root: string): '/' | '\\' => (root.includes('/') ? '/' : '\\')

const segmentsOf = (path: string, sep: string): string[] =>
  path.split(sep === '\\' ? /[\\/]/ : /\//)

const lastCut = (path: string, sep: string): number =>
  sep === '\\' ? Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\')) : path.lastIndexOf('/')

const trimEnd = (path: string, sep: string): string =>
  path.replace(sep === '\\' ? /[\\/]+$/ : /\/+$/, '')

const realOf = async ($: EngineInterface, path: string) =>
  $.fs.stat(path, { resolve: true }).catch(() => undefined)

/**
 * Where `path` lands once every symbolic link is followed, or undefined when
 * that cannot be said: the path itself if it exists, else its nearest existing
 * ancestor with the missing names appended. A `..` segment is never placed
 * (the tool and the file system fold it differently around a link).
 */
const place = async ($: EngineInterface, path: string, sep: string): Promise<string | undefined> => {
  const isPlaceable =
    path !== '' &&
    !/^[\\/][\\/]/.test(path) &&
    !/^[A-Za-z]:(?![\\/])/.test(path) &&
    !segmentsOf(path, sep).includes('..')
  if (!isPlaceable) return undefined

  const missing: string[] = []
  let head = path
  for (let depth = 0; depth < MAX_DEPTH; depth += 1) {
    const stat = await realOf($, head)
    if (stat !== undefined) {
      if (stat.realPath === undefined) return undefined
      return [trimEnd(stat.realPath, sep), ...missing].join(sep)
    }
    const trimmed = trimEnd(head, sep)
    if (trimmed === '' || trimmed === '.') return undefined
    const cut = lastCut(trimmed, sep)
    const name = trimmed.slice(cut + 1)
    if (/^[A-Za-z]:/.test(name)) return undefined
    if (name !== '.') missing.unshift(name)
    head = cut < 0 ? '.' : trimmed.slice(0, cut + 1)
  }
  return undefined
}

const locate = async ($: EngineInterface, path: string): Promise<Located> => {
  const root = (await $.fs.stat(await $.session.root(), { resolve: true })).realPath
  if (root === undefined) throw new Error('zap: the project root does not resolve')
  const sep = separatorOf(root)
  return {
    zapDir: `${trimEnd(root, sep)}${sep}${ZAP_DIR}`,
    real: await place($, path, sep),
  }
}

const isArmed = async ($: EngineInterface): Promise<boolean> => {
  try {
    return (await $.state.get(ARMED)).value === true
  } catch {
    // Not known to be armed: the guard stays out of the way.
    return false
  }
}

export const register: Register = on => {
  on('skill.prompt', { skill: 'zap:zap' }, async ($, e, next) => {
    await $.state.set(ARMED, true)
    return next(e)
  })

  on('tool.call', { tool: ['Write', 'Edit', 'NotebookEdit'] }, async ($, e, next) => {
    if (e.agentId !== undefined) return next(e)
    if (!(await isArmed($))) return next(e)

    // Armed from here on: anything thrown below is answered by `.catch`, a deny.
    const path = e.tool === 'NotebookEdit' ? e.notebook_path : e.file_path
    if (typeof path !== 'string') throw new Error('zap: the call names no path')

    const { zapDir, real } = await locate($, path)
    if (real === undefined) return { deny: refusal(path, 'its location cannot be resolved') }

    const sep = separatorOf(zapDir)
    if (!real.startsWith(zapDir + sep)) {
      return { deny: refusal(path, `it is outside ${zapDir}`) }
    }

    const ran = await next(e)
    const isWritten = ran.deny === undefined && ran.isError !== true
    if (isWritten && real === `${zapDir}${sep}${DIAGNOSIS}`) await $.state.set(ARMED, false)
    return ran
  }).catch(($, e, next) =>
    next.called
      ? next(e)
      : { deny: `zap: its write guard failed, so the write was refused. zap must write ${ZAP_DIR}/${DIAGNOSIS} before changing source.` },
  )
}

